// spec: .qa/e2e/specs/history.md (1.1)
// seed: tests/seed.user.spec.ts
import { test, expect } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });

// Убираем маркеры направления текста (RLM/LRM/изоляты).
const clean = (s: string) => s.replace(/[‎‏⁦-⁩]/g, '').replace(/\s+/g, ' ').trim();
const EVENT = /(בלי אירועים|התרעה אחת|\d+ התרעות|כשל אחד|\d+ כשלים)\s*$/;

test.describe('История — список и детали', () => {
  test('История: записи по дням с временем, длительностью и событиями; переход в детали; имена детей RTL #78e3149c @iphone @prod-safe', async ({ page }) => {
    // 1. /home → таб «היסטוריה»
    await page.goto('/home');
    await page.getByRole('tab', { name: 'היסטוריה' }).filter({ visible: true }).click();
    await expect(page).toHaveURL(/\/history$/);

    // 2. Группа дня: «היום» / «אתמול» / дата
    await expect(page.getByRole('heading', { name: /^(היום|אתמול|\d{1,2}\.\d{1,2}(\.\d{2,4})?)$/ }).filter({ visible: true }).first()).toBeVisible();

    // 3. Первые 10 записей: время, длительность, событие, иконка
    const rows = page.getByRole('button', { name: /ניטור, / }).filter({ visible: true });
    await expect(rows.nth(9)).toBeVisible();
    const data = await rows.evaluateAll((els) => els.slice(0, 10).map((el) => ({
      text: (el as HTMLElement).innerText,
      icon: !!el.querySelector('svg, img'),
    })));
    expect(data).toHaveLength(10);
    for (const r of data) {
      const t = clean(r.text);
      expect(t, 'время').toMatch(/\d{1,2}:\d{2}/);
      expect(t, 'длительность').toMatch(/\d+\s*(דק׳|שע׳|שנ׳)/);
      expect(t, 'событие').toMatch(EVENT);
      expect(r.icon, `иконка у «${t}»`).toBe(true);
    }

    // 4. Первая запись с тревогами (и детьми) → детали
    const alertRow = page.getByRole('button', { name: /QA בדיקה.*(התרעה אחת|\d+ התרעות)/ }).filter({ visible: true }).first();
    await alertRow.click();
    await expect(page).toHaveURL(/\/history\/.+/);
    await expect(page.getByRole('heading', { name: /התרע/ }).filter({ visible: true }).first()).toBeVisible();
    await expect(page.getByText(/זוהתה סכנה.*\d{1,2}:\d{2}/).filter({ visible: true }).first()).toBeVisible();

    // 5. Строка детей: RTL, текст слева от аватаров
    const kids = page.getByText(/QA בדיקה.*ו-.*QA קטן.*היו בבריכה/).filter({ visible: true }).last();
    await expect(kids).toBeVisible();
    expect(await kids.evaluate((el) => getComputedStyle(el).direction)).toBe('rtl');
    const geo = await kids.evaluate((el) => {
      const text = el.getBoundingClientRect();
      const avatars = el.parentElement!.firstElementChild!.getBoundingClientRect();
      return { textRight: text.right, avatarsLeft: avatars.left };
    });
    expect(geo.textRight, 'правый край текста не правее левого края аватаров').toBeLessThanOrEqual(geo.avatarsLeft + 1);
  });
});
